                if (dA.ApprovalStatus == "Discuss")
                    SET_DocumentApprove.DeleteDataByDocNoanddocTypeid(f_CompanyID, f_PeriodID, int.Parse(dA.DocumentNo), dA.DocumentTypeID, sqltrans, CurrentFiscalID);

                dA.DocumentApproveID = SET_DocumentApprove.GetNewDocumentApproveID(f_CompanyID, f_PeriodID, sqltrans);
                dA.FiscalID = CurrentFiscalID;
                dA.Insert(sqltrans);

                #endregion

                result = true;
            }
            catch (BusinessLogicException ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            finally
            {
                if (result)
                    SqlHelper.CommitTransaction(sqltrans);
                else
                    SqlHelper.RollBackTransaction(sqltrans, "UpdatePHeader");
            }

            return result;
        }

        public static DataTable GetDataForAdvancePaymentReceiptHSM(int companyID, int periodID, int CurrentFiscalID, Nullable<DateTime> DateFrom, Nullable<DateTime> DateTo, int? documentNoFrom, int? documentNoTo, int? Supplier, SqlConnection objConnection = null, SqlTransaction objTransaction = null)
        {
            DataTable dt = null;
            StringBuilder sb = new StringBuilder();

            #region Query
            const string Query_GetDataForAdvancePaymentReceiptHSM = @"SELECT AP_AdvanceSugarPayment.DocumentNo,AP_AdvanceSugarPayment.RecievingDate,AP_AdvanceSugarPayment.Quantity
,AP_AdvanceSugarPayment.Remarks,AP_AdvanceSugarPayment.AdvanceAmount,AP_AdvanceSugarPayment.FEDAmount,AP_AdvanceSugarPayment.FurtherTax
,AP_AdvanceSugarPayment.WithHoldingTax,SET_Business.BusinessName as SupplierName
,SET_Business.BusinessName + ' - ' + SET_OperatingUnit.OperatingUnitName  as SupplierNameComplete
,SET_Business.AddressLine1 as SupplierAddress, SET_Business.NTNNumber as SupplierNTN, SET_Business.PhoneNumber as SupplierPhoneNumber
,SET_OperatingUnit.FaxNumber as SupplierFaxNumber, SET_Business.SalesTaxNumber as SupplierSTRN, Brokername.CustomerName as BuyerName
,AR_SET_Customer.AddressLine1 as BuyerAddress, AR_SET_Customer.STRNNumber as BuyerSTRNNo, AR_SET_Customer.NTNNumber as BuyerNTNNo
,AR_SET_Customer.CustomerName,SET_OperatingUnit.AddressLine2, SET_OperatingUnit.Logoimage as LogoImage

FROM AP_AdvanceSugarPayment

INNER JOIN SET_Company ON SET_Company.CompanyId = AP_AdvanceSugarPayment.CompanyID AND SET_Company.Status=1
INNER JOIN SET_OperatingUnit On SET_OperatingUnit.OperatingUnitId=SET_Company.OperatingUnitId AND SET_OperatingUnit.Status=1
INNER JOIN SET_Business On SET_Business.BusinessId=SET_Company.BusinessId and SET_Business.IsActive=1
LEFT JOIN AR_SET_Customer Brokername ON Brokername.CustomerID = AP_AdvanceSugarPayment.BrokerID 
AND Brokername.CompanyID = AP_AdvanceSugarPayment.CompanyID
AND Brokername.PeriodID = AP_AdvanceSugarPayment.PeriodID
AND Brokername.Status = 1
LEFT JOIN AR_SET_Customer ON AR_SET_Customer.CustomerID = AP_AdvanceSugarPayment.CustomerID 
AND AR_SET_Customer.CompanyID = AP_AdvanceSugarPayment.CompanyID
AND AR_SET_Customer.PeriodID = AP_AdvanceSugarPayment.PeriodID
AND AR_SET_Customer.Status = 1

WHERE AP_AdvanceSugarPayment.CompanyID = @CompanyID
AND AP_AdvanceSugarPayment.PeriodID = @PeriodID
AND AP_AdvanceSugarPayment.CurrentFiscalID = @CurrentFiscalID
AND AP_AdvanceSugarPayment.RecievingDate BETWEEN @DateFrom AND @DateTo
{0}";
            #endregion

            try
            {
                SqlParameter[] sqlparams = new SqlParameter[5];
                sqlparams[0] = new SqlParameter("@CompanyID", companyID);
                sqlparams[1] = new SqlParameter("@PeriodID", periodID);
                sqlparams[2] = new SqlParameter("@CurrentFiscalID", CurrentFiscalID);
                sqlparams[3] = new SqlParameter("@DateFrom", DateFrom);
                sqlparams[4] = new SqlParameter("@DateTo", DateTo);

                if (documentNoFrom > 0 && documentNoTo > 0)
                    sb.Append(" AND AP_AdvanceSugarPayment.DocumentNo BETWEEN " + documentNoFrom + " AND " + documentNoTo);

                else if (documentNoFrom > 0)
                    sb.Append(" AND AP_AdvanceSugarPayment.DocumentNo = " + documentNoFrom);

                else if (documentNoTo > 0)
                    sb.Append(" AND AP_AdvanceSugarPayment.DocumentNo <= " + documentNoTo);

                if (Supplier > 0)
                    sb.Append(" AND AR_SET_Customer.CustomerID = " + Supplier);

                DataSet ds = null;

                if (objTransaction != null)
                    ds = SqlHelper.ExecuteDataset(objTransaction, CommandType.Text, Query_GetDataForAdvancePaymentReceiptHSM, sqlparams);
                else if (objConnection != null)
                    ds = SqlHelper.ExecuteDataset(objConnection, CommandType.Text, Query_GetDataForAdvancePaymentReceiptHSM, sqlparams);
                else
                    ds = SqlHelper.ExecuteDataset(CommandType.Text, string.Format(Query_GetDataForAdvancePaymentReceiptHSM, sb.ToString()), sqlparams);

                if (ds != null && ds.Tables != null && ds.Tables.Count > 0)
                    dt = ds.Tables[0];
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }

            return dt;
        }


